import{_ as e,c as r,o as i,af as n}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"10、【履】 兌下乾上","description":"溫公易說 - 10、【履】 兌下乾上","frontmatter":{"title":"10、【履】 兌下乾上","description":"溫公易說 - 10、【履】 兌下乾上"},"headers":[],"relativePath":"classics/wengong/011.md","filePath":"classics/wengong/011.md"}'),l={name:"classics/wengong/011.md"};function t(h,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[n('<h1 id="_10、【履】-兌下乾上" tabindex="-1">10、【履】 兌下乾上 <a class="header-anchor" href="#_10、【履】-兌下乾上" aria-label="Permalink to “10、【履】 兌下乾上”">​</a></h1><h3 id="彖曰-履-柔履剛也-說而應乎幹-是以履虎尾不咥人-亨。剛中正履-帝位而不疚-光明也。" tabindex="-1">彖曰：履，柔履剛也，說而應乎幹，是以履虎尾不咥人，亨。剛中正履，帝位而不疚，光明也。 <a class="header-anchor" href="#彖曰-履-柔履剛也-說而應乎幹-是以履虎尾不咥人-亨。剛中正履-帝位而不疚-光明也。" aria-label="Permalink to “彖曰：履，柔履剛也，說而應乎幹，是以履虎尾不咥人，亨。剛中正履，帝位而不疚，光明也。”">​</a></h3><h3 id="象曰-上天下澤-履。君子以辨上下-定民志。" tabindex="-1">象曰：上天下澤，履。君子以辨上下，定民志。 <a class="header-anchor" href="#象曰-上天下澤-履。君子以辨上下-定民志。" aria-label="Permalink to “象曰：上天下澤，履。君子以辨上下，定民志。”">​</a></h3><p>履者何？人之所履也。人之所履者何？禮之謂也。人有禮則生，無禮則死。禮者，人所履之常也。其曰辨上下，定民志者何？夫民生有欲，喜進務得而不可厭者也。不以禮節之，則貪淫侈溢而無窮也。是故先王作為禮以治之，使尊卑有等，長幼有倫，內外有別，親疏有序，然後上下各安其分而無覬覦之心。此先王制世御民之方也。</p><h3 id="初九-素履-往無咎-象曰-素履之往-獨行願也。" tabindex="-1">初九：素履，往無咎 象曰：素履之往，獨行願也。 <a class="header-anchor" href="#初九-素履-往無咎-象曰-素履之往-獨行願也。" aria-label="Permalink to “初九：素履，往無咎 象曰：素履之往，獨行願也。”">​</a></h3><h3 id="九二-履道坦坦-幽人貞吉-象曰-幽人貞吉-中不自亂也。" tabindex="-1">九二：履道坦坦，幽人貞吉 象曰：幽人貞吉，中不自亂也。 <a class="header-anchor" href="#九二-履道坦坦-幽人貞吉-象曰-幽人貞吉-中不自亂也。" aria-label="Permalink to “九二：履道坦坦，幽人貞吉 象曰：幽人貞吉，中不自亂也。”">​</a></h3><h3 id="六三-眇能視-跛能履-履虎尾-咥人兇。武人為於大君-象曰-眇能視-不足以有明也-跛能履-不足以與行也。咥人之兇-位不當也。武人為於大君-志剛也。" tabindex="-1">六三：眇能視，跛能履，履虎尾，咥人兇。武人為於大君 象曰：眇能視，不足以有明也；跛能履，不足以與行也。咥人之兇，位不當也。武人為於大君，志剛也。 <a class="header-anchor" href="#六三-眇能視-跛能履-履虎尾-咥人兇。武人為於大君-象曰-眇能視-不足以有明也-跛能履-不足以與行也。咥人之兇-位不當也。武人為於大君-志剛也。" aria-label="Permalink to “六三：眇能視，跛能履，履虎尾，咥人兇。武人為於大君 象曰：眇能視，不足以有明也；跛能履，不足以與行也。咥人之兇，位不當也。武人為於大君，志剛也。”">​</a></h3><h3 id="九四-履虎尾-訴訴-終吉-象曰-訴訴終吉-志行也。" tabindex="-1">九四：履虎尾，訴訴，終吉 象曰：訴訴終吉，志行也。 <a class="header-anchor" href="#九四-履虎尾-訴訴-終吉-象曰-訴訴終吉-志行也。" aria-label="Permalink to “九四：履虎尾，訴訴，終吉 象曰：訴訴終吉，志行也。”">​</a></h3><h3 id="九五-夬履-貞厲-象曰-夬履貞厲-位正當也。" tabindex="-1">九五：夬履，貞厲 象曰：夬履貞厲，位正當也。 <a class="header-anchor" href="#九五-夬履-貞厲-象曰-夬履貞厲-位正當也。" aria-label="Permalink to “九五：夬履，貞厲 象曰：夬履貞厲，位正當也。”">​</a></h3><p>夬者，決也。履者，人之所履也。人之所履有得有失，為人君者決而正之，得則有賞，失則有法。勸賞畏刑，然後人莫敢不慎其履，而天下國家可得而治也。五以剛健為履之主，乘其中正以決得失，任斯重也，可不戒乎？故曰貞厲。</p><h3 id="上九-視履-考祥-其旋-元吉-象曰-元吉在上-大有慶也。" tabindex="-1">上九：視履，考祥，其旋，元吉 象曰：元吉在上，大有慶也。 <a class="header-anchor" href="#上九-視履-考祥-其旋-元吉-象曰-元吉在上-大有慶也。" aria-label="Permalink to “上九：視履，考祥，其旋，元吉 象曰：元吉在上，大有慶也。”">​</a></h3>',11)])])}const f=e(l,[["render",t]]);export{b as __pageData,f as default};
